/* ------------------------------ helpers ------------------------------ */
function h(s){ return String(s===undefined||s===null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
function ic(name, cls){ var p = ICONS[name] || ICONS['circle']; return '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-'+name+' '+(cls||'w-4 h-4')+'" aria-hidden="true">'+p+'</svg>'; }
function num(v){ var n = parseFloat(v); return isNaN(n)?0:n; }
function fmt(n){ n = num(n); var neg = n<0; n = Math.abs(n); var r = Math.round(n*100)/100; var parts = r.toFixed(r%1?2:0).split('.'); var x = parts[0]; var last3 = x.slice(-3), rest = x.slice(0,-3); if(rest) last3 = ','+last3; rest = rest.replace(/\B(?=(\d{2})+(?!\d))/g, ','); return (neg?'-':'')+rest+last3+(parts[1]?'.'+parts[1]:''); }
function tk(n){ return '৳ '+fmt(n); }
function pad2(n){ return ('0'+n).slice(-2); }
function todayStr(){ var d=new Date(); return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate()); }
function dmy(s){ if(!s) return ''; var p=String(s).slice(0,10).split('-'); return p.length===3? p[2]+'-'+p[1]+'-'+p[0] : s; }
function emps(){ return (S.boot && S.boot.employees) || []; }
function empById(id){ var e = emps().filter(function(x){return x.id===id;}); return e[0]||null; }
function sett(){ return (S.boot && S.boot.settings) || { companyName:'Swarup Construction Solution', tagline:'Honesty is our Business Capital', categories:[], paymentModes:['Cash'], signatures:[], voucherTitle:'DAILY EXPENSE VOUCHER' }; }
function logoSrc(){ var l=sett().logo; return l ? (typeof signUrl==='function'?signUrl(l):l) : DEFAULT_LOGO; }
function isAdmin(){ return S.role==='admin'; }

/* Taka in words (Bangladeshi system) */
function inWords(amount){
  amount = Math.round(num(amount)*100)/100;
  var ones=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
  var tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
  function two(n){ return n<20?ones[n]:tens[Math.floor(n/10)]+(n%10?' '+ones[n%10]:''); }
  function three(n){ var hh=Math.floor(n/100), r=n%100; return (hh?ones[hh]+' Hundred'+(r?' ':''):'')+(r?two(r):''); }
  function conv(n){ if(n===0) return ''; var out=[]; var cr=Math.floor(n/10000000); n%=10000000; var lk=Math.floor(n/100000); n%=100000; var th=Math.floor(n/1000); n%=1000;
    if(cr) out.push(conv(cr)+' Crore'); if(lk) out.push(two(lk)+' Lakh'); if(th) out.push(two(th)+' Thousand'); if(n) out.push(three(n)); return out.join(' '); }
  var neg = amount<0; amount=Math.abs(amount);
  var taka=Math.floor(amount), paisa=Math.round((amount-taka)*100);
  var s = taka? conv(taka)+' Taka' : 'Zero Taka';
  if(paisa) s += ' and '+two(paisa)+' Paisa';
  return (neg?'Minus ':'')+s+' Only';
}

/* ------------------------------ server ------------------------------ */
function api(fn){
  var args = Array.prototype.slice.call(arguments,1);
  return new Promise(function(res, rej){
    if(typeof google==='undefined' || !google.script || !google.script.run){ rej(new Error('Google Apps Script সংযোগ নেই (Web App হিসেবে ডিপ্লয় করে খুলুন)।')); return; }
    var r = google.script.run.withSuccessHandler(res).withFailureHandler(function(err){
      var msg = (err && err.message) || String(err);
      if(msg.indexOf('AUTH:')>=0){ doLogout(true); toast(msg.replace(/^.*AUTH:\s*/,''),'error'); }
      rej(new Error(msg.replace(/^Error:\s*/,'').replace(/^Exception:\s*/,'')));
    });
    r[fn].apply(r, args);
  });
}
var busyCount = 0;
function busy(on){ busyCount += on?1:-1; if(busyCount<0) busyCount=0; var b=document.getElementById('scs-busy'); if(b) b.style.display = busyCount? 'block':'none'; }
function call(fn){ var a = arguments; busy(true); return api.apply(null, a).then(function(r){ busy(false); return r; }, function(e){ busy(false); toast(e.message,'error'); throw e; }); }

/* ------------------------------ toast ------------------------------ */
var toastTimer=null;
function toast(msg, type){
  var el = document.getElementById('toast-root'); if(!el) return;
  var c = type==='error' ? 'bg-rose-950/90 border-rose-700 text-rose-100' : type==='info' ? 'bg-slate-900/90 border-slate-700 text-slate-100' : 'bg-emerald-950/90 border-emerald-700 text-emerald-100';
  var i = type==='error' ? ic('circle-alert','w-4 h-4 text-rose-400') : type==='info' ? ic('info','w-4 h-4 text-sky-400') : ic('circle-check','w-4 h-4 text-emerald-500');
  el.innerHTML = '<div class="fixed bottom-5 right-5 z-[70] animate-slide-up pointer-events-none max-w-[90vw]"><div class="flex items-center gap-2.5 px-4 py-3 rounded-2xl shadow-2xl border text-xs font-semibold '+c+'">'+i+'<span>'+h(msg)+'</span></div></div>';
  clearTimeout(toastTimer); toastTimer = setTimeout(function(){ el.innerHTML=''; }, 3500);
}

/* ------------------------------ status badge ------------------------------ */
function ticks(v){
  if(!v || v.status!=='Approved') return '';
  var n=(v.appr1At?1:0)+(v.appr2At?1:0); if(!n) n=1;
  return '<span title="'+n+'/2 approved" class="inline-flex items-center -space-x-2 text-emerald-600">'+ic('check','w-4 h-4 stroke-[3.5]')+(n>1?ic('check','w-4 h-4 stroke-[3.5]'):'')+'</span>';
}
function badge(st, v){
  /* Pending shows nothing; Approved shows only green ticks (one per approver) */
  if(st==='Submitted') return '';
  if(st==='Approved') return ticks(v||{status:'Approved', appr1At:1});
  var m = { Draft:'bg-slate-100 text-slate-700 border-slate-300 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-600',
    Submitted:'bg-amber-50 text-amber-700 border-amber-300 dark:bg-amber-950/50 dark:text-amber-300 dark:border-amber-800',
    Returned:'bg-rose-50 text-rose-700 border-rose-300 dark:bg-rose-950/50 dark:text-rose-300 dark:border-rose-800',
    Approved:'bg-emerald-50 text-emerald-700 border-emerald-300 dark:bg-emerald-950/50 dark:text-emerald-300 dark:border-emerald-800' };
  var i = { Draft:'file-pen-line', Submitted:'clock', Returned:'undo-2', Approved:'badge-check' };
  return '<span class="inline-flex items-center gap-1 text-[10px] sm:text-[11px] px-2 py-0.5 rounded-full font-bold border whitespace-nowrap '+(m[st]||m.Draft)+'">'+ic(i[st]||'circle','w-3 h-3')+'<span>'+h(t(st))+'</span></span>'+ticks(v);
}

/* ------------------------------ layout ------------------------------ */
/* SCS: পিন-লগইন স্ক্রিন বাদ (SCS অ্যাকাউন্টই লগইন) */
function renderLogin(){ return SCS.startHTML(); }

/* update PIN dots and the go-button in place (no full re-render, so nothing jumps) */
function pinPaint(dotsId, pin, btnId){
  var box=document.getElementById(dotsId); if(!box) return;
  var on='bg-pink-600 scale-125 shadow-md shadow-pink-500/50', off='bg-slate-200 dark:bg-slate-700';
  var need=Math.max(4, pin.length);
  while(box.children.length<need){ var d=document.createElement('div'); d.className='w-4 h-4 rounded-full transition-all duration-150 '+off; box.appendChild(d); }
  while(box.children.length>need) box.removeChild(box.lastChild);
  for(var i=0;i<box.children.length;i++) box.children[i].className='w-4 h-4 rounded-full transition-all duration-150 '+(pin.length>i?on:off);
  var b=document.getElementById(btnId); if(b) b.disabled = pin.length<4;
}
function pinKey(k){
  if(S.pinBusy) return;
  if(k==='C') S.pin=''; else if(k==='B') S.pin=S.pin.slice(0,-1); else if(S.pin.length<8) S.pin+=k;
  pinPaint('pin-dots', S.pin, 'pin-go');
  clearTimeout(S.pinT);
  var apl=parseInt(LS.get('scs_apl')||'4',10);
  if(/^[0-9]$/.test(k) && S.pin.length>=4){ if(S.pin.length>=apl) doLogin(); else S.pinT=setTimeout(doLogin, 900); }
}
function doLogin(){
  if(S.pin.length<4 || S.pinBusy) return;
  S.pinBusy=true; render();
  api('login', S.pin).then(function(r){
    S.pinBusy=false;
    if(!r.ok){ S.pin=''; render(); toast(r.message || 'Invalid PIN','error'); return; }
    S.token=r.token; S.role=r.role; S.pin=''; LS.set('scs_exp_token',r.token); LS.set('scs_exp_role',r.role);
    toast(S.lang==='bn'?(r.role==='admin'?'স্বাগতম! অ্যাডমিন হিসেবে লগইন হয়েছে।':'স্বাগতম! সফলভাবে লগইন হয়েছে।'):(r.role==='admin'?'Welcome! Logged in as Admin.':'Welcome! Logged in successfully.'),'success');
    boot();
  }, function(e){ S.pinBusy=false; S.pin=''; render(); toast(e.message,'error'); });
}
function doLogout(silent){
  LS.set('scs_boot', null); S.boot=null; S.vview=null;
  if(S.token && !silent) api('logout', S.token).catch(function(){});
  S.token=''; S.role=''; S.boot=null; S.dash=null; S.all.data=null; S.admin.queue=null; S.modal=null; S.page='dashboard';
  LS.set('scs_exp_token',null); LS.set('scs_exp_role',null);
  render();
}
function toggleLang(){ S.lang = S.lang==='bn'?'en':'bn'; LS.set('scs_exp_lang',S.lang); render(); }
function toggleDark(){ S.dark=!S.dark; LS.set('scs_exp_dark',S.dark?'1':'0'); applyDark(); }
function applyDark(){ document.documentElement.classList.toggle('dark', S.dark); }

