function subChips(){
  var bn=S.lang==='bn', L=[];
  if(S.page==='new'){
    var dc=S.ne.drafts?S.ne.drafts.length:'';
    L=[ {on:S.ne.tab==='edit', fn:"neTab('edit')", icon:'file-plus', label:bn?'খরচ যোগ':'Add Expense'},
        {on:S.ne.tab==='drafts', fn:"neTab('drafts')", icon:'folder-open', label:bn?'সেভড ড্রাফট':'Saved Drafts', count:'<span id="ne-dcount" class="min-w-5 h-5 px-1 rounded-full bg-amber-500 text-white text-[10px] flex items-center justify-center">'+dc+'</span>'} ];
  } else {
    var bc=S.all.back?S.all.back.length:(S.ne.back||'');
    L=[ {on:S.all.tab==='all', fn:"expenseTab('all')", icon:'layers', label:bn?'সকল খরচ':'All Expenses'},
        {on:S.all.tab==='back', fn:"expenseTab('back')", icon:'undo-2', label:bn?'ফেরত আসা (Send Back)':'Send Back', count:bc!==''?'<span id="back-count" class="min-w-5 h-5 px-1 rounded-full bg-rose-500 text-white text-[10px] flex items-center justify-center">'+bc+'</span>':''} ];
  }
  return L.map(function(c){ return '<button type="button" onclick="'+c.fn+'" class="'+(c.on?CHIP_ON:CHIP_OFF)+'">'+ic(c.icon,'w-4 h-4 '+(c.on?'text-white':'text-pink-600'))+'<span>'+h(c.label)+'</span>'+(c.count||'')+'</button>'; }).join('');
}
