function barList(rows, labelFn, valFn, color, onclickFn){
  if(!rows.length) return '<p class="text-xs text-slate-500">'+h(t('noData'))+'</p>';
  var max = Math.max.apply(null, rows.map(valFn).concat([1]));
  return '<div class="space-y-2.5">'+rows.map(function(r){
    var v=valFn(r), w=Math.max(3, Math.round(v/max*100));
    return '<div '+(onclickFn?'onclick="'+onclickFn(r)+'" class="cursor-pointer group"':'')+'><div class="flex items-center justify-between text-xs mb-1"><span class="font-semibold text-slate-700 dark:text-slate-200 group-hover:text-pink-600 truncate pr-2">'+labelFn(r)+'</span><span class="font-black font-mono text-slate-900 dark:text-slate-100 whitespace-nowrap">'+tk(v)+'</span></div><div class="h-2 rounded-full bg-slate-100 dark:bg-slate-800 overflow-hidden"><div class="h-full rounded-full bg-gradient-to-r '+color+'" style="width:'+w+'%"></div></div></div>';
  }).join('')+'</div>';
}

