/* ---------- on-screen signature pad (touch / mouse) with Clear, Undo, Redo ---------- */
function signModal(M){
  var bn=S.lang==='bn';
  var b='flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs font-bold bg-slate-100 text-slate-800 border border-slate-300 dark:bg-slate-700 dark:text-white dark:border-slate-500 cursor-pointer active:scale-95';
  return '<div class="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4 bg-slate-950/70"><div class="w-full sm:max-w-lg rounded-t-3xl sm:rounded-3xl p-4 shadow-2xl border bg-white border-slate-200 dark:bg-slate-900 dark:border-slate-800 animate-slide-up">'+
    '<div class="flex items-center justify-between mb-1"><h3 class="font-bold text-sm flex items-center gap-2">'+ic('signature','w-4 h-4 text-pink-600')+h(bn?'আপনার সিগনেচার দিন':'Sign to submit')+'</h3><button type="button" onclick="closeModal()" class="p-1 rounded-lg text-slate-400 cursor-pointer">'+ic('x','w-5 h-5')+'</button></div>'+
    '<p class="text-[11px] text-slate-500 mb-2">'+h(bn?'আঙুল বা মাউস দিয়ে নিচের বক্সে সই করুন। এটি ভাউচারের "Prepared By" ঘরে বসবে। না দিতে চাইলে "সিগনেচার ছাড়া" চাপুন।':'Sign in the box with your finger or mouse. It goes in the "Prepared By" box of the voucher. Or tap "Skip signature".')+(M.extra?' <b class="text-pink-600">'+h(M.extra)+'</b>':'')+'</p>'+
    '<div class="rounded-2xl border-2 border-dashed border-slate-300 dark:border-slate-600 bg-white overflow-hidden"><canvas id="sign-pad" class="w-full block touch-none cursor-crosshair" style="height:170px"></canvas></div>'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mt-2"><div class="flex gap-1.5"><button type="button" onclick="signUndo()" class="'+b+'">'+ic('undo-2','w-3.5 h-3.5')+h(bn?'আন্ডু':'Undo')+'</button><button type="button" onclick="signRedo()" class="'+b+'">'+ic('redo-2','w-3.5 h-3.5')+h(bn?'রিডু':'Redo')+'</button><button type="button" onclick="signClear()" class="'+b+' text-rose-600">'+ic('eraser','w-3.5 h-3.5')+h(bn?'ক্লিয়ার':'Clear')+'</button></div>'+
    '<div class="flex gap-1.5 ml-auto"><button type="button" onclick="signNext(true)" class="px-3 py-1.5 rounded-xl border border-slate-300 dark:border-slate-600 text-slate-600 dark:text-slate-300 text-xs font-bold cursor-pointer active:scale-95">'+h(bn?'সিগনেচার ছাড়া':'Skip signature')+'</button>'+
    '<button type="button" onclick="signNext()" class="flex items-center gap-1.5 px-4 py-1.5 rounded-xl bg-pink-600 hover:bg-pink-700 text-white text-xs font-bold cursor-pointer active:scale-95">'+h(bn?'পরবর্তী: পিন':'Next: PIN')+ic('arrow-right','w-3.5 h-3.5')+'</button></div></div></div></div>';
}
var SP=null;
function initSignPad(){
  var c=document.getElementById('sign-pad'); if(!c) return;
  var r=c.getBoundingClientRect(), dpr=window.devicePixelRatio||1;
  c.width=Math.round(r.width*dpr); c.height=Math.round(r.height*dpr);
  SP={ c:c, ctx:c.getContext('2d'), dpr:dpr, cur:null };
  signDraw();
  var pos=function(e){ var b=c.getBoundingClientRect(); return [ (e.clientX-b.left), (e.clientY-b.top) ]; };
  c.addEventListener('pointerdown', function(e){ e.preventDefault(); c.setPointerCapture(e.pointerId); SP.cur=[pos(e)]; S.modal.strokes.push(SP.cur); S.modal.redo=[]; signDraw(); });
  c.addEventListener('pointermove', function(e){ if(!SP.cur) return; e.preventDefault(); SP.cur.push(pos(e)); signDraw(); });
  var end=function(){ SP.cur=null; };
  c.addEventListener('pointerup', end); c.addEventListener('pointercancel', end); c.addEventListener('pointerleave', end);
}
function signDraw(target, scale, ox, oy){
  var ctx = target || (SP && SP.ctx); if(!ctx) return;
  var M=S.modal, k = scale || (SP?SP.dpr:1);
  if(!target){ ctx.clearRect(0,0,SP.c.width,SP.c.height); }
  ctx.lineCap='round'; ctx.lineJoin='round'; ctx.strokeStyle='#0b1a5c'; ctx.lineWidth=2.4*k;
  (M.strokes||[]).forEach(function(st){
    ctx.beginPath();
    st.forEach(function(p,i){ var x=(p[0]-(ox||0))*k, y=(p[1]-(oy||0))*k; if(i===0){ ctx.moveTo(x,y); ctx.lineTo(x+0.1,y+0.1); } else ctx.lineTo(x,y); });
    ctx.stroke();
  });
}
function signUndo(){ var M=S.modal; if(M.strokes.length){ M.redo.push(M.strokes.pop()); signDraw(); } }
function signRedo(){ var M=S.modal; if(M.redo.length){ M.strokes.push(M.redo.pop()); signDraw(); } }
function signClear(){ var M=S.modal; if(M.strokes.length){ M.redo=M.strokes.slice().reverse(); M.strokes=[]; signDraw(); } }
function signExport(){
  var M=S.modal, x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;
  M.strokes.forEach(function(st){ st.forEach(function(p){ x0=Math.min(x0,p[0]); y0=Math.min(y0,p[1]); x1=Math.max(x1,p[0]); y1=Math.max(y1,p[1]); }); });
  var pad=6; x0-=pad; y0-=pad; x1+=pad; y1+=pad;
  var w=x1-x0, hh=y1-y0, sc=Math.min(2, 360/w, 120/hh);
  var cv=document.createElement('canvas'); cv.width=Math.max(10,Math.round(w*sc)); cv.height=Math.max(10,Math.round(hh*sc));
  signDraw(cv.getContext('2d'), sc, x0, y0);
  var url=cv.toDataURL('image/png');
  if(url.length>45000){ var c2=document.createElement('canvas'); c2.width=Math.round(cv.width/2); c2.height=Math.round(cv.height/2); c2.getContext('2d').drawImage(cv,0,0,c2.width,c2.height); url=c2.toDataURL('image/png'); }
  return url;
}

/* ============================== EXPENSE › ALL EXPENSES / SEND BACK ============================== */
function allFilter(){
  var a=S.all;
  var f = { mode:a.mode, empId:a.empId, status:a.status, withItems: true };
  if(a.mode==='date') f.date=a.date;
  if(a.mode==='month'){ f.year=S.year; f.month=S.month; }
  if(a.mode==='year') f.year=S.year;
  if(a.mode==='range'){ f.from=a.from; f.to=a.to; }
  return f;
}
var QC={};
function loadAll(silent){
  if(!S.boot) return;
  if(S.all.tab==='back'){ loadBack(); return; }
  var f=allFilter(), key=JSON.stringify(f);
  if(QC[key]){ S.all.data=QC[key]; S.all.loading=false; } else if(!silent) S.all.loading=true;
  (QC[key]?api:call)('listVouchers', S.token, f).then(function(r){ QC[key]=r.vouchers; S.all.loading=false; if(JSON.stringify(allFilter())!==key) return; S.all.data=r.vouchers; if(S.page==='all' && !S.vview) render(); }, function(){ S.all.loading=false; render(); });
  api('listVouchers', S.token, { mode:'lifetime', status:'Returned' }).then(function(r){ S.all.back=r.vouchers; var c=document.getElementById('back-count'); if(c) c.textContent=r.vouchers.length; }).catch(function(){});
}
function loadBack(){
  S.all.back=null;
  call('listVouchers', S.token, { mode:'lifetime', status:'Returned' }).then(function(r){ S.all.back=r.vouchers; if(S.page==='all') render(); }).catch(function(){});
}
function setAll(k, v){ S.all[k]=v; render(); if(k!=='view' && k!=='sort') loadAll(); }
function periodLabel(){
  var a=S.all;
  if(a.mode==='date') return dmy(a.date);
  if(a.mode==='month') return mName(S.month)+' '+S.year;
  if(a.mode==='year') return String(S.year);
  if(a.mode==='range') return (a.from?dmy(a.from):'…')+' — '+(a.to?dmy(a.to):'…');
  return t('fLife');
}
function reportTitle(){
  var a=S.all, base = a.view==='emp' ? 'EMPLOYEE-WISE EXPENSE REPORT' : 'DAILY EXPENSE REPORT';
  var p = a.mode==='month' ? MONTHS[S.month-1].toUpperCase()+'-'+S.year : a.mode==='year' ? 'YEAR-'+S.year : a.mode==='date' ? dmy(a.date) : a.mode==='range' ? periodLabel() : 'LIFETIME';
  return base+' '+p;
}
function reportSub(){
  var a=S.all, parts=[];
  var e = a.empId? empById(a.empId) : null;
  parts.push(t('employee')+': '+(e? e.name+' ('+e.id+')' : (a.empId||t('allEmp'))));
  parts.push(t('status')+': '+(a.status==='All'?'All':t(a.status)));
  return parts.join('   •   ');
}
function sortList(list, k){
  var ts=function(v){ return (v.date||'')+' '+(v.submittedAt||v.updatedAt||v.createdAt||''); };
  return (list||[]).slice().sort(function(a,b){ var x=ts(a), y=ts(b); return k==='old' ? (x<y?-1:x>y?1:0) : (x<y?1:x>y?-1:0); });
}
function sortedData(){
  var d=(S.all.data||[]).slice(), k=S.all.sort;
  var ts=function(v){ return v.date+' '+(v.submittedAt||v.updatedAt||v.createdAt||''); };
  d.sort(function(a,b){
    if(k==='old') return ts(a)<ts(b)?-1:ts(a)>ts(b)?1:0;
    if(k==='amtHi') return b.total-a.total;
    if(k==='amtLo') return a.total-b.total;
    if(k==='name') return a.empName.localeCompare(b.empName) || (a.date<b.date?1:-1);
    return ts(a)<ts(b)?1:ts(a)>ts(b)?-1:0;
  });
  return d;
}
