    '<div>'+lbl(t('empId')+' *')+'<input type="text" value="'+h(E.id)+'" oninput="S.admin.emp.id=this.value" placeholder="E001" class="'+inputCls('font-mono font-bold')+'"></div>'+
    '<div class="lg:col-span-2">'+lbl(t('empName')+' *')+'<input type="text" value="'+h(E.name)+'" oninput="S.admin.emp.name=this.value" class="'+inputCls('font-bold')+'"></div>'+
    '<div>'+lbl(t('designation'))+'<input type="text" value="'+h(E.designation)+'" oninput="S.admin.emp.designation=this.value" class="'+inputCls()+'"></div>'+
    '<div>'+lbl(t('mobile'))+'<input type="text" value="'+h(E.mobile)+'" oninput="S.admin.emp.mobile=this.value" class="'+inputCls('font-mono')+'"></div>'+
    '<div>'+lbl(S.lang==='bn'?'ব্যক্তিগত সাবমিট পিন (ঐচ্ছিক)':'Personal Submit PIN (optional)')+'<input type="text" inputmode="numeric" maxlength="8" value="'+h(E.pin)+'" oninput="S.admin.emp.pin=this.value.replace(/\\D/g,\'\');this.value=S.admin.emp.pin" placeholder="2019" class="'+inputCls('font-mono')+'"></div>'+
    '<div class="sm:col-span-2 lg:col-span-6 flex flex-wrap items-center justify-between gap-2"><label class="flex items-center gap-2 text-xs font-semibold cursor-pointer"><input type="checkbox" '+(E.active?'checked':'')+' onchange="S.admin.emp.active=this.checked" class="w-4 h-4 accent-pink-600"> Active</label><div class="flex gap-2">'+(E._orig?'<button type="button" onclick="S.admin.emp=null;render()" class="px-4 py-2 rounded-xl bg-slate-100 dark:bg-slate-800 text-xs font-bold border border-slate-200 dark:border-slate-700 cursor-pointer">'+h(t('cancel'))+'</button>':'')+'<button type="button" onclick="saveEmp()" class="px-5 py-2 rounded-xl bg-pink-600 hover:bg-pink-700 text-white text-xs font-bold shadow-xs flex items-center gap-1.5 cursor-pointer active:scale-95 transition-all">'+ic('save','w-3.5 h-3.5')+'<span>'+h(E._orig?(S.lang==='bn'?'আপডেট করুন':'Update Employee'):(S.lang==='bn'?'এমপ্লয়ি যোগ করুন':'Add Employee'))+'</span></button></div></div></div>'+
    '<p class="text-[11px] text-slate-400">'+h(S.lang==='bn'?'ব্যক্তিগত পিন দিলে সেই এমপ্লয়ি শুধু নিজের পিন দিয়ে সাবমিট করতে পারবে। খালি রাখলে ইউজার পিন (2019) দিয়ে সাবমিট হবে।':'If a personal PIN is set, that employee must submit with it. If blank, the common user PIN (2019) is used.')+'</p>';
  var list=emps();
  var rows=list.map(function(e,ix){ return '<tr class="hover:bg-slate-50 dark:hover:bg-slate-800/40"><td class="py-2 px-2 text-slate-400 font-bold">'+(ix+1)+'</td><td class="py-2 px-3 font-mono font-bold">'+h(e.id)+'</td><td class="py-2 px-3 font-semibold">'+h(e.name)+'</td><td class="py-2 px-3">'+h(e.designation)+'</td><td class="py-2 px-3 font-mono">'+h(e.mobile)+'</td><td class="py-2 px-3">'+(e.pin?'<span class="font-mono">••••</span>':'<span class="text-slate-400">2019</span>')+'</td><td class="py-2 px-3">'+(e.active?'<span class="text-emerald-600 font-bold">Active</span>':'<span class="text-slate-400 font-bold">Inactive</span>')+'</td><td class="py-2 px-3 text-right whitespace-nowrap"><button type="button" title="Up" onclick="moveEmp(\''+h(e.id)+'\',-1)" class="p-1.5 rounded-lg text-slate-500 hover:text-pink-600 hover:bg-pink-50 cursor-pointer">'+ic('arrow-up','w-3.5 h-3.5')+'</button><button type="button" title="Down" onclick="moveEmp(\''+h(e.id)+'\',1)" class="p-1.5 rounded-lg text-slate-500 hover:text-pink-600 hover:bg-pink-50 cursor-pointer">'+ic('arrow-down','w-3.5 h-3.5')+'</button><button type="button" onclick="editEmp(\''+h(e.id)+'\')" class="p-1.5 rounded-lg text-slate-500 hover:text-pink-600 hover:bg-pink-50 cursor-pointer">'+ic('pen-line','w-3.5 h-3.5')+'</button><button type="button" onclick="delEmp(\''+h(e.id)+'\')" class="p-1.5 rounded-lg text-slate-500 hover:text-rose-600 hover:bg-rose-50 cursor-pointer">'+ic('trash-2','w-3.5 h-3.5')+'</button></td></tr>'; }).join('');
  return adminCard(E._orig?'user-pen':'user-plus', E._orig?(S.lang==='bn'?'এমপ্লয়ি এডিট':'Edit Employee'):(S.lang==='bn'?'নতুন এমপ্লয়ি যোগ':'Add New Employee'), form)+
    adminCard('users', (S.lang==='bn'?'এমপ্লয়ি তালিকা':'Employee List')+' ('+list.length+')', miniTable('<th class="py-2 px-2">#</th><th class="py-2 px-3">ID</th><th class="py-2 px-3">'+h(t('empName'))+'</th><th class="py-2 px-3">'+h(t('designation'))+'</th><th class="py-2 px-3">'+h(t('mobile'))+'</th><th class="py-2 px-3">PIN</th><th class="py-2 px-3">'+h(t('status'))+'</th><th class="py-2 px-3"></th>', rows));
