function bkRestoreSrc(src, label){
  var bn=S.lang==='bn';
  confirmBox(bn?'এই ব্যাকআপ থেকে রিস্টোর করবেন?':'Restore from this backup?', label+(bn?' — বর্তমান সব ডাটা এই ব্যাকআপ দিয়ে বদলে যাবে (আগে নিজে থেকে একটা ব্যাকআপ নেওয়া হবে)।':' — all current data will be replaced by this backup (a safety backup is taken first).'), function(){
    askPin(t('adminPin'), bn?'রিস্টোর করতে অ্যাডমিন পিন দিন':'Enter the admin PIN to restore', function(pin, M){
      api('restoreBackup', S.token, pin, src).then(function(c){ bkAfterRestore(M, c); }, function(e){ pinFail(M, e); });
    });
  });
}
function bkRestore(id, time){ bkRestoreSrc({ fileId:id }, time); }
function bkRestoreFile(inp){
  var f=inp.files && inp.files[0]; if(!f) return;
  var r=new FileReader(); r.onload=function(){ inp.value=''; bkRestoreSrc({ json:String(r.result) }, f.name); }; r.readAsText(f);
}
function bkReset(scope){
  var bn=S.lang==='bn', all=scope==='all';
  confirmBox(all?(bn?'পুরো অ্যাপ রিসেট করবেন?':'Reset the whole app?'):(bn?'সব খরচ ও ভাউচার মুছবেন?':'Erase all expenses & vouchers?'), bn?'আগে নিজে থেকে Google Drive-এ ব্যাকআপ নেওয়া হবে, তারপর মুছবে।':'A backup is saved to Google Drive first, then the data is erased.', function(){
    promptBox(bn?'নিশ্চিত করতে RESET লিখুন':'Type RESET to confirm', bn?'এই কাজ ফেরানো যাবে না (শুধু ব্যাকআপ থেকে রিস্টোর করা যাবে)। চালিয়ে যেতে বড় হাতের অক্ষরে RESET লিখুন।':'This cannot be undone except by restoring a backup. Type RESET in capitals to continue.', bn?'চালিয়ে যান':'Continue', 'bg-rose-600 hover:bg-rose-700', function(txt){
    if(String(txt||'').trim()!=='RESET'){ toast(bn?'RESET লেখা মেলেনি। রিসেট হয়নি।':'RESET was not typed. Nothing was reset.','error'); return; }
    askPin(t('adminPin'), bn?'রিসেট করতে অ্যাডমিন পিন দিন':'Enter the admin PIN to reset', function(pin, M){
      api('resetData', S.token, pin, scope).then(function(){
        S.modal=null; renderModal(); QC={}; S.admin.bk=null; S.all.data=null; S.admin.queue=null;
        toast(bn?'রিসেট হয়েছে।':'Reset done.','success');
        if(all){ doLogout(true); render(); return; }
        call('getBootstrap', S.token).then(function(b){ S.boot=b; loadAdminTab(); render(); });
      }, function(e){ pinFail(M, e); });
    });
    });
  });
}
